gip(){return"\u0627\u062f\u0631\u0633 3 \u0645\u0631\u0627\u062d\u0644 \u0645\u0646 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0623\u0648 \u0627\u0644\u0645\u0633\u062a\u062d\u0642\u0629 \u0641\u064a \u0643\u0644 \u0637\u0627\u0628\u0642."},
giq(){return"79 \u062f\u0648\u0631\u0629 \u0634\u0647\u0627\u062f\u0627\u062a \u0639\u0628\u0631 20 \u0644\u063a\u0629 \u2014 \u062a\u062d\u062a\u0641\u0638 \u0643\u0644 \u062f\u0648\u0631\u0629 \u0628\u062a\u0642\u062f\u0645\u0647\u0627 \u0627\u0644\u062e\u0627\u0635."},
giw(){return"\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0648\u0627\u0644\u062f\u0645\u062c"},
git(){return"\u0623\u062c\u0628 \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u0644\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0643\u0631\u0627\u062a \u0627\u0644\u0647\u0644\u0627\u0645\u060c \u062b\u0645 \u0623\u0633\u0642\u0637\u0647\u0627 \u0648\u0627\u062f\u0645\u062c\u0647\u0627 \u062d\u062a\u0649 2048."},
