gli(){return"\u042d\u043d\u0435\u0440\u0433\u0438\u044f \u0440\u0430\u0441\u0445\u043e\u0434\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0443\u0447\u0451\u0431\u044b \u0438\u043b\u0438 \u0438\u0433\u0440\u044b \u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0437\u0430 24 \u0447\u0430\u0441\u0430."},
glj(){return"\u0417\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0434\u0430\u0451\u0442\u0441\u044f \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0448\u0430\u0440; \u0437\u0430 \u043e\u0448\u0438\u0431\u043a\u0443 \u0438\u043b\u0438 \u0438\u0441\u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u2014 \u0441\u0430\u043c\u044b\u0439 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0439 \u0448\u0442\u0440\u0430\u0444\u043d\u043e\u0439 \u0448\u0430\u0440."},
glk(){return"\u0420\u0430\u0443\u043d\u0434 \u0437\u0430\u043a\u0430\u043d\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f, \u043a\u043e\u0433\u0434\u0430 \u0448\u0430\u0440\u044b \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u044f\u044e\u0442 \u043a\u043e\u0440\u0437\u0438\u043d\u0443."},
gll(){return"\u041f\u043e\u0431\u0435\u0434\u0430 \u043d\u0430\u0434 \u0431\u043e\u0441\u0441\u043e\u043c \u0432 \u0438\u0433\u0440\u0435 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0435\u0451 \u0432 \u0426\u0435\u043d\u0442\u0440\u0435 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438; \u0441\u0440\u0430\u0437\u0438\u0442\u0435\u0441\u044c \u0441 \u0431\u043e\u0441\u0441\u043e\u043c \u0441\u043d\u043e\u0432\u0430, \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0438\u0433\u0440\u044b."},
glm(){return"79 \u043a\u0443\u0440\u0441\u043e\u0432 \u043f\u043e 20 \u044f\u0437\u044b\u043a\u0430\u043c \u2014 \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u0430 \u0441\u0432\u043e\u0438 \u044d\u0442\u0430\u0436\u0438, \u043a\u043e\u043b\u043e\u0434\u0430 SRS \u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u043d\u0430\u0432\u044b\u043a\u0438."},
glh(){return"\u041a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c"},
glc(){return"\u0414\u043b\u044f \u0441\u0430\u0439\u0442\u0430 \u043d\u0435 \u043d\u0443\u0436\u0435\u043d \u0430\u043a\u043a\u0430\u0443\u043d\u0442, \u0438 \u043e\u043d \u043d\u0435 \u043e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0435\u0442 \u0432\u0430\u0441: \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u044f\u0437\u044b\u043a."},
gld(){return"\u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0431\u0435\u0437 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430: \u043f\u0440\u043e\u0431\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435. \u0421\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0434\u043b\u044f \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u043c\u0438."},
gle(){return"\u041c\u0438\u043a\u0440\u043e\u0444\u043e\u043d \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438, \u043f\u043e\u043a\u0430 \u0432\u044b \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0443 \u0440\u0435\u0447\u0438 \u0432 \xab\u041f\u043e\u0432\u0442\u043e\u0440\u0435 \u0433\u043e\u043b\u043e\u0441\u043e\u043c\xbb. Pandlish \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0432\u0430\u0441."},
