gim(){return"\u0421\u043b\u0435\u0434\u0443\u044e\u0449\u0430\u044f \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430"},
gir(){return"\u041f\u0443\u0442\u044c \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f"},
gio(){return"\u041a\u0430\u0436\u0434\u0430\u044f \u0442\u0435\u043c\u0430 \u2014 \u044d\u0442\u043e \u0431\u0430\u0448\u043d\u044f \u0438\u0437 \u044d\u0442\u0430\u0436\u0435\u0439, \u0430 \u041f\u0430\u043d\u0434\u0438 \u2014 \u0432\u0430\u0448 \u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a."},
